-- Dados de exemplo · Escola Sabatina, 4º trimestre 2026 (esquema v4)
-- Tirados de Quadro_Comparativo_Grupos_1.xlsx (os valores da planilha são exemplos).
BEGIN;
SELECT set_config('app.usuario_id', '1', true);
SELECT setval(pg_get_serial_sequence('nucleo.usuario', 'usu_id'), (SELECT max(usu_id) FROM nucleo.usuario));
SELECT setval(pg_get_serial_sequence('organizacao.entidade', 'ent_id'), (SELECT max(ent_id) FROM organizacao.entidade));
SELECT setval(pg_get_serial_sequence('organizacao.igreja', 'igr_id'), (SELECT max(igr_id) FROM organizacao.igreja));
SELECT setval(pg_get_serial_sequence('escola_sabatina.trimestre', 'etr_id'), (SELECT max(etr_id) FROM escola_sabatina.trimestre));
SELECT setval(pg_get_serial_sequence('escola_sabatina.sabado', 'esa_id'), (SELECT max(esa_id) FROM escola_sabatina.sabado));
SELECT setval(pg_get_serial_sequence('escola_sabatina.classe', 'ecl_id'), (SELECT max(ecl_id) FROM escola_sabatina.classe));
SELECT setval(pg_get_serial_sequence('escola_sabatina.classe_trimestre', 'ect_id'), (SELECT max(ect_id) FROM escola_sabatina.classe_trimestre));
SELECT setval(pg_get_serial_sequence('secretaria.membro', 'mem_id'), (SELECT max(mem_id) FROM secretaria.membro));
COMMIT;
